"""Batch scan: emit global_repeated_word_accept for invalid 3+ letter words that appear globally 3+ times."""

import re
from collections import Counter

from scripts.dictionary_loader import get_english_dictionary, is_valid_word_for_rules

# Same tokenization as awareness / repeated_word_accept: non-whitespace runs.
WORD_RE = re.compile(r"\S+")
_LETTER_DIGIT_APOSTROPHE_RE = re.compile(r"[a-zA-Z0-9']+")
_ORDINAL_RE = re.compile(r"^\d+(?:st|nd|rd|th)$", re.IGNORECASE)
_YEAR_RE = re.compile(r"^(?:19|20)\d{2}$")
_MIN_LETTERS = 3
_MIN_GLOBAL_COUNT = 3

RULE_ID = "global_repeated_word_accept"


def _is_valid_subspan(part: str, dic: object) -> bool:
    """Return True if part is valid (dict or stem), or ordinal, or year, or all digits. Edited by Cursor."""
    if not part:
        return False
    if is_valid_word_for_rules(part, dic):  # type: ignore[arg-type]
        return True
    if _ORDINAL_RE.fullmatch(part):
        return True
    if _YEAR_RE.fullmatch(part):
        return True
    return bool(part.isdigit())


def _is_token_valid(token: str, dic: object) -> bool:
    """Return True if every letter/digit/apostrophe span is valid. Edited by Cursor."""
    for m in _LETTER_DIGIT_APOSTROPHE_RE.finditer(token):
        span = m.group(0)
        if span and not _is_valid_subspan(span, dic):
            return False
    return True


def _token_core_length(token: str) -> int:
    """Length of letter/digit/apostrophe core (longest span). Edited by Cursor."""
    max_len = 0
    for m in _LETTER_DIGIT_APOSTROPHE_RE.finditer(token):
        max_len = max(max_len, len(m.group(0)))
    return max_len


def build_global_counts_chunk(
    full_text: str,
    turn_boundaries: list[tuple[int, int, str, int]],
    dic: object,
) -> Counter[str]:
    """Return Counter of lowercase invalid tokens (3+ letters or single letter invalid for rules). Edited by Cursor."""
    counts: Counter[str] = Counter()
    for start, end, _pstr, _ti in turn_boundaries:
        turn_text = full_text[start:end]
        for m in WORD_RE.finditer(turn_text):
            tok = m.group(0)
            if _is_token_valid(tok, dic):
                continue
            core_len = _token_core_length(tok)
            if core_len < _MIN_LETTERS and core_len != 1:
                continue
            counts[tok.lower()] += 1
    return counts


def scan_batch_global_repeated_word_accept(
    full_text: str,
    path_str: str,  # noqa: ARG001
    turn_boundaries: list[tuple[int, int, str, int]],
    global_counts: Counter[str],
) -> list[tuple[str, int, int, str, str]]:
    """Emit (rule_id, turn_index, start_index, span, path_str) for each occurrence of an invalid 3+ letter word with global count >= 3."""
    if not turn_boundaries:
        return []
    dic = get_english_dictionary()
    out: list[tuple[str, int, int, str, str]] = []
    for start, end, pstr, turn_index in turn_boundaries:
        turn_text = full_text[start:end]
        for m in WORD_RE.finditer(turn_text):
            tok = m.group(0)
            if _is_token_valid(tok, dic):
                continue
            core_len = _token_core_length(tok)
            # Allow single letters invalid for rules; otherwise require 3+ letters. Edited by Cursor.
            if core_len < _MIN_LETTERS and core_len != 1:
                continue
            if global_counts.get(tok.lower(), 0) < _MIN_GLOBAL_COUNT:
                continue
            out.append((RULE_ID, turn_index, m.start(), tok, pstr))
    return out
